#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up Android push for reminders (ADR-0010): a Firebase project, its
# google-services.json in the app, and its FCM V1 service-account key in EAS.
# Run from anywhere: bash mobile/scripts/setup-android-push.sh

run_wizard() {

MOBILE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_DIR="$(cd "$MOBILE_DIR/.." && pwd)"
cd "$MOBILE_DIR"
PACKAGE=$(node -p 'require("./app.json").expo.android.package')
FIREBASE="https://console.firebase.google.com/"

TOTAL_STAGES=6

banner "Android push for reminders"

stage "Firebase: create a project"
say "Android push goes through Firebase Cloud Messaging, so the app needs a Firebase project."
open_url "$FIREBASE"
step "Click 'Create a project' (or pick an existing one you want to reuse)."
step "Name it (e.g. 'Movie Night'). Google Analytics is not needed; turn it off."
step "Wait for the project to be ready, then open it."
pause "Press Enter once the project is open."

stage "Firebase: register the Android app"
say "Register the app under its package name so Firebase issues its config file."
open_url "$FIREBASE"
step "In the project overview, click 'Add app' and choose the Android icon."
step "Android package name: ${BOLD}${PACKAGE}${RESET} (nickname optional; skip the SHA-1)."
step "Click 'Register app', then 'Download google-services.json'."
step "Skip Firebase's remaining SDK steps: Expo's plugins do that part."
GOOGLE_SERVICES_DOWNLOAD="$HOME/Downloads/google-services.json"
ask GOOGLE_SERVICES_DOWNLOAD "Path to the downloaded file (Enter for ~/Downloads/google-services.json):" || true
GOOGLE_SERVICES_DOWNLOAD="${GOOGLE_SERVICES_DOWNLOAD:-$HOME/Downloads/google-services.json}"
GOOGLE_SERVICES_DOWNLOAD="${GOOGLE_SERVICES_DOWNLOAD/#\~/$HOME}"
until [[ -f "$GOOGLE_SERVICES_DOWNLOAD" ]] && grep -q "\"$PACKAGE\"" "$GOOGLE_SERVICES_DOWNLOAD"; do
  warn "$GOOGLE_SERVICES_DOWNLOAD is missing or isn't for $PACKAGE."
  ask GOOGLE_SERVICES_DOWNLOAD "Path to google-services.json:"
  GOOGLE_SERVICES_DOWNLOAD="${GOOGLE_SERVICES_DOWNLOAD/#\~/$HOME}"
done
cp "$GOOGLE_SERVICES_DOWNLOAD" "$MOBILE_DIR/google-services.json"
printf '  %s✓ copied%s google-services.json → mobile/google-services.json\n' "$GREEN" "$RESET"
node -e '
  const fs = require("fs");
  const app = JSON.parse(fs.readFileSync("app.json", "utf8"));
  app.expo.android.googleServicesFile = "./google-services.json";
  fs.writeFileSync("app.json", JSON.stringify(app, null, 2) + "\n");
'
printf '  %s✓ set%s expo.android.googleServicesFile in mobile/app.json\n' "$GREEN" "$RESET"
note "google-services.json holds only public identifiers; commit it with app.json."
pause

stage "Firebase: generate the service-account key"
say "Expo's push service sends to FCM with this key. It is a credential: keep it out of the repo."
open_url "$FIREBASE"
step "Open the project, click the gear → 'Project settings' → 'Service accounts'."
step "Click 'Generate new private key', then 'Generate key'. A JSON file downloads."
step "Move it somewhere outside this repo (e.g. ~/.secrets/)."
FCM_KEY_PATH=""
until [[ -f "$FCM_KEY_PATH" ]] && grep -q '"private_key"' "$FCM_KEY_PATH"; do
  [[ -n "$FCM_KEY_PATH" ]] && warn "$FCM_KEY_PATH is missing or isn't a service-account key."
  ask FCM_KEY_PATH "Path to the service-account key JSON:"
  FCM_KEY_PATH="${FCM_KEY_PATH/#\~/$HOME}"
done
FCM_KEY_PATH="$(cd "$(dirname "$FCM_KEY_PATH")" && pwd)/$(basename "$FCM_KEY_PATH")"
if [[ "$FCM_KEY_PATH" == "$REPO_DIR"/* ]]; then
  warn "That key is inside the repo. Move it out before committing anything."
  pause "Press Enter once it's moved (the next stage asks for its path again)."
fi

stage "EAS: upload the key"
say "Expo's push service needs the key to deliver to Android devices."
if ! eas whoami >/dev/null 2>&1; then
  say "First, log in to the Expo account that owns this project."
  eas login
fi
note "Logged in as $(eas whoami 2>/dev/null | head -n1)."
say "Next, 'eas credentials' runs. In its menus choose:"
step "Android → any build profile (development is fine; the key is per app)."
step "Google Service Account → 'Manage your Google Service Account Key for Push Notifications (FCM V1)'."
step "'Set up a Google Service Account Key for Push Notifications (FCM V1)' → 'Upload a new service account key'."
step "When asked for the file, give: ${BOLD}${FCM_KEY_PATH}${RESET} (or the path you moved it to)."
step "Then exit the menus."
pause "Press Enter to run eas credentials."
eas credentials || warn "eas credentials exited with an error; re-run it by hand if the key isn't listed."
note "Check: expo.dev → project → Credentials → Android should list an FCM V1 service account key."
pause

stage "Rebuild the dev client"
say "google-services.json and expo-notifications are native config, so android/ must be regenerated."
warn "This deletes the generated android/ folder (it's gitignored and rebuilt)."
step "In another terminal, with your phone connected, run:"
printf '\n      %scd %s && just android-clean%s\n\n' "$BOLD" "$MOBILE_DIR" "$RESET"
step "Start the backend too (cd backend && just run) so the app can register."
step "On the phone: open the app, allow notifications, then Settings → 'Reminders & nudges'."
step "It should show a switch. 'Not on this device' means the push token still failed."
pause "Press Enter once the switch shows."

stage "Optional: send a test push"
say "This reads the newest registered push token from the local database and sends one test notification."
if confirm "Send a test push now?"; then
  DATABASE_URL="${DATABASE_URL:-$(grep -E '^DATABASE_URL=' "$REPO_DIR/backend/.env" 2>/dev/null | cut -d= -f2- | tr -d "'\"")}"
  DATABASE_URL="${DATABASE_URL:-postgres://movie:movie@localhost:5432/movienight?sslmode=disable}"
  PUSH_TOKEN=$(psql "$DATABASE_URL" -Atc "SELECT push_token FROM devices WHERE push_token IS NOT NULL ORDER BY last_seen_at DESC LIMIT 1" 2>/dev/null || true)
  if [[ -z "$PUSH_TOKEN" ]]; then
    warn "No registered push token found. Reopen the app with the backend running, then retry."
    SKIPPED+=("test push (no device has registered a push token yet)")
  else
    note "Sending to $PUSH_TOKEN"
    curl -sS -H 'Content-Type: application/json' -X POST https://exp.host/--/api/v2/push/send \
      -d "$(jq -n --arg to "$PUSH_TOKEN" '{to: $to, title: "Test reminder", body: "Android push is set up.", channelId: "reminders"}')"
    printf '\n'
    say "A ticket with \"status\":\"ok\" means Expo accepted it; the phone should show it now."
    pause
  fi
fi

finish
say "Commit mobile/google-services.json and mobile/app.json. Never commit the service-account key."
printf '\n'
}

run_wizard "$@"; exit
